// Landmark footprints for placement (src/world/footprints.js, generated: do not edit by hand).
// Builds every registered landmark module (and the placeholder example.js) in node over a few
// seeds and, for modules whose geometry depends on built / decay, a few states, and records the
// polar envelope of everything standing above 5 cm (rig parts and FX cards excluded: rigs are
// built at the origin and move; reach covers them): per 1-degree bin around the origin, the
// furthest point (landmark-local x, z). Long triangles are sampled along their edges, so a
// 600 m track made of few triangles still counts. sites.js keeps every road clear of this
// envelope (and of the pad) when it places a landmark.
//   node tools/footprints.mjs           regenerate src/world/footprints.js
//   node tools/footprints.mjs --check   exit 1 if the file is stale (tools/clearance-test.mjs runs it)
import { readFileSync, writeFileSync } from 'node:fs';
import { LandmarkBuilder, beginBuild } from '../src/world/landmarks/kit.js';
import * as MODULES from '../src/world/landmarks/index.js';
import example from '../src/world/landmarks/example.js';

export const BINS = 360;
const OUT = new URL('../src/world/footprints.js', import.meta.url).pathname;
const SEEDS = [1, 7, 4242, 123457, 99991];
const STATES = [[1, 0], [1, 0.5], [1, 1], [0.6, 0]];

export function envelope(def, b) {
  const ex = new Float64Array(BINS), ez = new Float64Array(BINS), er = new Float64Array(BINS);
  const add = (x, z) => {
    const r = x * x + z * z;
    let k = Math.floor((Math.atan2(z, x) + Math.PI) / (2 * Math.PI) * BINS);
    if (k >= BINS) k = 0;
    if (r > er[k]) { er[k] = r; ex[k] = x; ez[k] = z; }
  };
  const states = def.live ? [[1, 0]] : STATES;
  for (const seed of SEEDS) {
    for (const [bu, de] of states) {
      const it = beginBuild(def, b, bu, de, seed, def.biome);
      if (it) while (!it.next().done);
      const f = b.f, t = b.tu8;
      const ok = (v) => f[v * 8 + 1] > 0.05 && ((t[v * 24 + 6] >> 2) & 7) === 0;
      for (let v = 0; v < b.nv; v++) if (ok(v)) add(f[v * 8], f[v * 8 + 2]);
      for (let L = 0; L < 2; L++) {
        const I = L ? b.aidx : b.idx, n = L ? b.na : b.ni;
        for (let q = 0; q < n; q += 3) {
          const a = I[q], c = I[q + 1], d = I[q + 2];
          if (!(ok(a) || ok(c) || ok(d))) continue;
          for (const [u, w] of [[a, c], [c, d], [d, a]]) {
            const ux = f[u * 8], uz = f[u * 8 + 2], wx = f[w * 8], wz = f[w * 8 + 2];
            const len = Math.hypot(wx - ux, wz - uz);
            if (len < 3) continue;
            const m = Math.ceil(len / 3);
            for (let k = 1; k < m; k++) add(ux + (wx - ux) * k / m, uz + (wz - uz) * k / m);
          }
        }
      }
    }
  }
  // Int16 x, z at 0.1 m per bin (0, 0: nothing in that direction).
  const q = new Int16Array(BINS * 2);
  for (let k = 0; k < BINS; k++) {
    q[k * 2] = Math.max(-32767, Math.min(32767, Math.round(ex[k] * 10)));
    q[k * 2 + 1] = Math.max(-32767, Math.min(32767, Math.round(ez[k] * 10)));
  }
  return Buffer.from(q.buffer).toString('base64');
}

export function generate() {
  const b = new LandmarkBuilder();
  const out = {};
  for (const k of Object.keys(MODULES).sort()) out[k] = envelope(MODULES[k], b);
  out.example = envelope(example, b);
  let src = '// Generated by tools/footprints.mjs from the landmark modules: do not edit by hand.\n';
  src += '// Per module (export name in landmarks/index.js): the polar envelope of what stands above 5 cm,\n';
  src += `// ${BINS} bins around the origin from angle -pi, each the furthest point as Int16 x, z (0.1 m), base64.\n`;
  src += `export const FOOT_BINS = ${BINS};\nexport const FOOTPRINTS = {\n`;
  for (const k in out) src += `  ${k}: '${out[k]}',\n`;
  src += '};\n';
  return src;
}

if (import.meta.url === `file://${process.argv[1]}`) {
  const src = generate();
  if (process.argv.includes('--check')) {
    let old = '';
    try { old = readFileSync(OUT, 'utf8'); } catch {}
    if (old !== src) { console.log('src/world/footprints.js is stale: run node tools/footprints.mjs'); process.exit(1); }
    console.log('footprints up to date');
  } else {
    writeFileSync(OUT, src);
    console.log(`wrote ${OUT} (${src.length} bytes)`);
  }
}
